3	import (
4		"errors"
5		"flag"
6		"fmt"
7		"io"
8	)
9	
10	// timeFmt 是命令行展示时间的格式（JSON 文件内使用 RFC3339）。
11	const timeFmt = "2006-01-02 15:04:05 -0700"
12	
13	// newFlagSet 为子命令准备统一的解析器：错误不自动退出，也不自行打印，
14	// 全部交由 parseFlags 统一输出，避免重复提示。
15	func newFlagSet(name string, _ io.Writer) *flag.FlagSet {
16		fs := flag.NewFlagSet(name, flag.ContinueOnError)
17		fs.SetOutput(io.Discard)
18		fs.Usage = func() {}
19		return fs
20	}
21	
22	// parseFlags 解析子命令参数。第二个返回值是退出码；ok=false 时应直接退出。
23	func parseFlags(fs *flag.FlagSet, argv []string, stdout, stderr io.Writer, printCmdHelp func(io.Writer)) (ok bool, code int) {
24		if err := fs.Parse(argv); err != nil {
25			if errors.Is(err, flag.ErrHelp) {
26				printCmdHelp(stdout)
27				return false, exitOK
28			}
29			fmt.Fprintf(stderr, "%s %s: %v；运行 %s %s --help 查看用法\n", appName, fs.Name(), err, appName, fs.Name())
30			return false, exitUsage
31		}
32		if fs.NArg() > 0 {
33			fmt.Fprintf(stderr, "%s %s: 未知参数 %q；运行 %s %s --help 查看用法\n", appName, fs.Name(), fs.Arg(0), appName, fs.Name())
34			return false, exitUsage
35		}
36		return true, 0
37	}
38	
39	func cmdRegister(dataFile string, argv []string, stdout, stderr io.Writer) int {
40		fs := newFlagSet("register", stderr)
41		fs.StringVar(&dataFile, "data", dataFile, "本地台账数据文件路径")
42		id := fs.String("id", "", "包裹编号（不可为空或仅含空白）")
43		station := fs.String("station", "", "收件站点（不可为空或仅含空白）")
44		if ok, code := parseFlags(fs, argv, stdout, stderr, printRegisterHelp); !ok {
45			return code
46		}
47	
48		cleanIDVal, err := cleanID("包裹编号", *id)
49		if err != nil {
50			fmt.Fprintf(stderr, "%s register: %v\n", appName, err)
51			return exitBusiness
52		}
53		cleanStation, err := cleanID("收件站点", *station)
54		if err != nil {
55			fmt.Fprintf(stderr, "%s register: %v\n", appName, err)
56			return exitBusiness
57		}
58	
59		store, err := Open(dataFile)
60		if err != nil {
61			fmt.Fprintf(stderr, "%s register: %v\n", appName, err)
62			return exitBusiness
63		}
64		p, err := store.Register(cleanIDVal, cleanStation, now())
65		if err != nil {
66			fmt.Fprintf(stderr, "%s register: %v\n", appName, err)
67			return exitBusiness
68		}
69	
70		fmt.Fprintf(stdout, `收件登记成功
71	包裹编号: %s
72	收件站点: %s
73	当前状态: %s
74	发生时间: %s
75	`, p.ID, p.Station, p.Status, p.Registered.Format(timeFmt))
76		return exitOK
77	}
78	
79	func cmdQuery(dataFile string, argv []string, stdout, stderr io.Writer) int {
80		fs := newFlagSet("query", stderr)
81		fs.StringVar(&dataFile, "data", dataFile, "本地台账数据文件路径")
82		id := fs.String("id", "", "要查询的包裹编号")
83		if ok, code := parseFlags(fs, argv, stdout, stderr, printQueryHelp); !ok {
84			return code
85		}
86	
87		cleanIDVal, err := cleanID("包裹编号", *id)
88		if err != nil {
89			fmt.Fprintf(stderr, "%s query: %v\n", appName, err)
90			return exitBusiness
91		}
92	
93		store, err := Open(dataFile)
94		if err != nil {
95			fmt.Fprintf(stderr, "%s query: %v\n", appName, err)
96			return exitBusiness
97		}
98		p, err := store.Query(cleanIDVal)
99		if err != nil {
100			fmt.Fprintf(stderr, "%s query: %v\n", appName, err)
101			return exitBusiness
102		}
103	
104		fmt.Fprintf(stdout, "包裹编号: %s\n当前站点: %s\n当前状态: %s\n轨迹（按提交顺序，共 %d 条）:\n",
105			p.ID, p.Station, p.Status, len(p.Trail))
106		for i, e := range p.Trail {
107			req := e.Request
108			if req == "" {
109				req = "-"
110			}
111			fmt.Fprintf(stdout, "  %d. 操作: %s    站点: %s    请求号: %s    时间: %s\n",
112				i+1, e.Op, e.Station, req, e.Time.Format(timeFmt))
113		}
114		return exitOK
115	}
116	
117	func cmdHandoff(dataFile string, argv []string, stdout, stderr io.Writer) int {
118		fs := newFlagSet("handoff", stderr)
119		fs.StringVar(&dataFile, "data", dataFile, "本地台账数据文件路径")
120		request := fs.String("request", "", "交接请求号（用于去重）")
121		from := fs.String("from", "", "源站点")
122		to := fs.String("to", "", "目的站点")
123		var parcels stringList
124		fs.Var(&parcels, "parcel", "包裹编号，可重复指定；集合不可为空或含重复编号")
125		if ok, code := parseFlags(fs, argv, stdout, stderr, printHandoffHelp); !ok {
126			return code
127		}
128	
129		cleanReq, err := cleanID("请求号", *request)
130		if err != nil {
131			fmt.Fprintf(stderr, "%s handoff: %v\n", appName, err)
132			return exitBusiness
133		}
134		cleanFrom, err := cleanID("源站点", *from)
135		if err != nil {
136			fmt.Fprintf(stderr, "%s handoff: %v\n", appName, err)
137			return exitBusiness
138		}
139		cleanTo, err := cleanID("目的站点", *to)
140		if err != nil {
141			fmt.Fprintf(stderr, "%s handoff: %v\n", appName, err)
142			return exitBusiness
143		}
144		if len(parcels) == 0 {
145			fmt.Fprintf(stderr, "%s handoff: 包裹集合不可为空，至少需要一个 --parcel\n", appName)
146			return exitBusiness
147		}
148		cleanParcels := make([]string, 0, len(parcels))
149		seen := make(map[string]bool, len(parcels))
150		for _, raw := range parcels {
151			id, err := cleanID("包裹编号", raw)
152			if err != nil {
153				fmt.Fprintf(stderr, "%s handoff: %v\n", appName, err)
154				return exitBusiness
155			}
156			if seen[id] {
157				fmt.Fprintf(stderr, "%s handoff: 包裹集合中编号 %q 重复\n", appName, id)
158				return exitBusiness
159			}
160			seen[id] = true
161			cleanParcels = append(cleanParcels, id)
162		}
163		if cleanFrom == cleanTo {
164			fmt.Fprintf(stderr, "%s handoff: 源站点与目的站点不能相同（均为 %q）\n", appName, cleanFrom)
165			return exitBusiness
166		}
167	
168		store, err := Open(dataFile)
169		if err != nil {
170			fmt.Fprintf(stderr, "%s handoff: %v\n", appName, err)
171			return exitBusiness
172		}
173		result, replayed, err := store.Handoff(cleanReq, cleanFrom, cleanTo, cleanParcels, now())
174		if err != nil {
175			fmt.Fprintf(stderr, "%s handoff: %v\n", appName, err)
176			return exitBusiness
177		}
178	
179		headline := "交接成功"
180		if replayed {
181			headline = "交接成功（请求号重复提交，返回首次保存的结果，未再追加轨迹）"
182		}
183		fmt.Fprintf(stdout, "%s\n请求号: %s\n源站点: %s\n目的站点: %s\n包裹（%d 件）:\n",
184			headline, result.Request, result.From, result.To, len(result.Parcels))
185		for _, id := range result.Parcels {
186			fmt.Fprintf(stdout, "  - %s\n", id)
187		}
188		fmt.Fprintf(stdout, "发生时间: %s\n", result.Time.Format(timeFmt))
189		return exitOK
190	}
