1	package main
2	
3	import (
4		"errors"
5		"os"
6		"path/filepath"
7		"strings"
8		"testing"
9		"time"
10	)
11	
12	func tClock(y int, mo time.Month, d, h, min int) time.Time {
13		return time.Date(y, mo, d, h, min, 0, 0, time.UTC)
14	}
15	
16	func openTempStore(t *testing.T) (*Store, string) {
17		t.Helper()
18		dir := t.TempDir()
19		path := filepath.Join(dir, "ledger.json")
20		s, err := Open(path)
21		if err != nil {
22			t.Fatalf("Open 不存在的文件失败: %v", err)
23		}
24		return s, path
25	}
26	
27	func mustRegister(t *testing.T, s *Store, id, station string, now time.Time) {
28		t.Helper()
29		if _, err := s.Register(id, station, now); err != nil {
30			t.Fatalf("Register(%q) 意外失败: %v", id, err)
31		}
32	}
33	
34	func TestRegisterAndQuery(t *testing.T) {
35		s, _ := openTempStore(t)
36		now := tClock(2026, 10, 5, 9, 0)
37	
38		p, err := s.Register("P001", "站点A", now)
39		if err != nil {
40			t.Fatalf("Register 失败: %v", err)
41		}
42		if p.Station != "站点A" || p.Status != statusInStation {
43			t.Fatalf("登记后站点/状态不符: %+v", p)
44		}
45		if len(p.Trail) != 1 || p.Trail[0].Op != "收件" || p.Trail[0].Station != "站点A" ||
46			!p.Trail[0].Time.Equal(now) || p.Trail[0].Request != "" {
47			t.Fatalf("收件记录不符: %+v", p.Trail)
48		}
49	
50		got, err := s.Query("P001")
51		if err != nil {
52			t.Fatalf("Query 失败: %v", err)
53		}
54		if got.Station != "站点A" || len(got.Trail) != 1 {
55			t.Fatalf("查询结果不符: %+v", got)
56		}
57	
58		if _, err := s.Query("NOPE"); !errors.Is(err, ErrNotFound) {
59			t.Fatalf("不存在的包裹应返回 ErrNotFound，得到 %v", err)
60		}
61	}
62	
63	func TestDuplicateRegisterDoesNotOverwrite(t *testing.T) {
64		s, _ := openTempStore(t)
65		mustRegister(t, s, "P001", "站点A", tClock(2026, 10, 5, 9, 0))
66	
67		if _, err := s.Register("P001", "站点B", tClock(2026, 10, 5, 10, 0)); err == nil {
68			t.Fatal("重复登记必须报错")
69		}
70		p, _ := s.Query("P001")
71		if p.Station != "站点A" || len(p.Trail) != 1 {
72			t.Fatalf("重复登记不得覆盖原记录: %+v", p)
73		}
74	}
75	
76	func TestHandoffSuccess(t *testing.T) {
77		s, _ := openTempStore(t)
78		t1 := tClock(2026, 10, 5, 9, 0)
79		mustRegister(t, s, "P001", "站点A", t1)
80		mustRegister(t, s, "P002", "站点A", t1)
81	
82		t2 := tClock(2026, 10, 5, 11, 30)
83		res, replayed, err := s.Handoff("R1", "站点A", "站点B", []string{"P001", "P002"}, t2)
84		if err != nil || replayed {
85			t.Fatalf("交接应成功且非重放: %v replayed=%v", err, replayed)
86		}
87		if res.Request != "R1" || res.From != "站点A" || res.To != "站点B" ||
88			len(res.Parcels) != 2 || res.Parcels[0] != "P001" || res.Parcels[1] != "P002" {
89			t.Fatalf("交接结果不符: %+v", res)
90		}
91	
92		for _, id := range []string{"P001", "P002"} {
93			p, _ := s.Query(id)
94			if p.Station != "站点B" || p.Status != statusInStation {
95				t.Fatalf("%s 交接后应在站点B且在站: %+v", id, p)
96			}
97			if len(p.Trail) != 2 {
98				t.Fatalf("%s 应有两条轨迹，得到 %d", id, len(p.Trail))
99			}
100			e := p.Trail[1]
101			if e.Op != "交接" || e.Station != "站点B" || e.Request != "R1" || !e.Time.Equal(t2) {
102				t.Fatalf("%s 交接记录不符: %+v", id, e)
103			}
104		}
105	}
106	
107	func TestHandoffFailsAtomicWhenAnyParcelInvalid(t *testing.T) {
108		s, path := openTempStore(t)
109		t1 := tClock(2026, 10, 5, 9, 0)
110		mustRegister(t, s, "P001", "站点A", t1)
111		mustRegister(t, s, "P002", "站点A", t1)
112		mustRegister(t, s, "P003", "站点C", t1) // 不属于源站点 A
113		before, err := os.ReadFile(path)
114		if err != nil {
115			t.Fatal(err)
116		}
117	
118		cases := []struct {
119			name    string
120			parcels []string
121		}{
122			{"含未登记包裹", []string{"P001", "GHOST"}},
123			{"含非源站点包裹", []string{"P001", "P003"}},
124		}
125		for _, c := range cases {
126			t.Run(c.name, func(t *testing.T) {
127				if _, _, err := s.Handoff("RX", "站点A", "站点B", c.parcels, tClock(2026, 10, 5, 12, 0)); err == nil {
128					t.Fatal("存在不合规包裹时整次交接必须失败")
129				}
130				for _, id := range []string{"P001", "P002", "P003"} {
131					p, _ := s.Query(id)
132					wantStation := map[string]string{"P001": "站点A", "P002": "站点A", "P003": "站点C"}[id]
133					if p.Station != wantStation || len(p.Trail) != 1 {
134						t.Fatalf("失败交接不得改动 %s: station=%q trail=%d", id, p.Station, len(p.Trail))
135					}
136				}
137				after, _ := os.ReadFile(path)
138				if string(after) != string(before) {
139					t.Fatal("失败交接不得写入数据文件")
140				}
141			})
142		}
143	}
144	
145	func TestFailedHandoffDoesNotOccupyRequest(t *testing.T) {
146		s, _ := openTempStore(t)
147		t1 := tClock(2026, 10, 5, 9, 0)
148		mustRegister(t, s, "P001", "站点A", t1)
149	
150		// 首次提交失败（包裹在站点C，不在源站点B）。
151		if _, _, err := s.Handoff("R1", "站点B", "站点X", []string{"P001"}, t1); err == nil {
152			t.Fatal("首次提交应失败")
153		}
154		// 纠正原因后用同一请求号重试，应当成功。
155		res, replayed, err := s.Handoff("R1", "站点A", "站点B", []string{"P001"}, tClock(2026, 10, 5, 10, 0))
156		if err != nil || replayed {
157			t.Fatalf("纠正后重试应作为新交接成功: %v replayed=%v", err, replayed)
158		}
159		if res.To != "站点B" {
160			t.Fatalf("重试结果不符: %+v", res)
161		}
162	}
163	
164	func TestHandoffIdempotentReplay(t *testing.T) {
165		s, _ := openTempStore(t)
166		t1 := tClock(2026, 10, 5, 9, 0)
167		mustRegister(t, s, "P001", "站点A", t1)
168		mustRegister(t, s, "P002", "站点A", t1)
169	
170		first, _, err := s.Handoff("R1", "站点A", "站点B", []string{"P001", "P002"}, tClock(2026, 10, 5, 10, 0))
171		if err != nil {
172			t.Fatal(err)
173		}
174	
175		// 相同内容、集合顺序不同：必须返回首次结果且不追加轨迹。
176		again, replayed, err := s.Handoff("R1", "站点A", "站点B", []string{"P002", "P001"}, tClock(2026, 10, 5, 11, 0))
177		if err != nil || !replayed {
178			t.Fatalf("同内容重复提交应重放: %v replayed=%v", err, replayed)
179		}
180		if again != first {
