// newFlagSet 为子命令准备统一的解析器：错误不自动退出，也不自行打印，
// 全部交由 parseFlags 统一输出，避免重复提示。
func newFlagSet(name string, _ io.Writer) *flag.FlagSet {
	fs := flag.NewFlagSet(name, flag.ContinueOnError)
	fs.SetOutput(io.Discard)
	fs.Usage = func() {}
