func TestCLIEndToEndReturn(t *testing.T) {
	dbPath := t.TempDir() + "/ledger.json"

	runCLI(t, dbPath, "register", "--id", "P001", "--station", "站点A")
	runCLI(t, dbPath, "register", "--id", "P002", "--station", "站点A")
